class AdoptionAggregator(BaseModule):
    def forward(...):
        # Effective wearing rate (supply-constrained)
        effective = sum(1 for p in persons if getattr(p, 'effective_wearing', 0) == 1)
        effective_rate = effective / float(max(1, N))
        buffers['observable.adoption_rate_daily'] = effective_rate
        # Adoption clustering (adopter-adopter edge share)
        adj = state.get('adjacency') or [set() for _ in range(N)]
        adopter_edges = 0
        total_edges = 0
        for u in range(N):
            for v in adj[u]:
                if u < v:
                    total_edges += 1
                    if persons[u].adopted == 1 and persons[v].adopted == 1:
                        adopter_edges += 1
        buffers['metric.adoption_clustering'] = (adopter_edges / float(total_edges)) if total_edges > 0 else 0.0
        # Influence attribution aggregation
        atts = buffers.get('attribution.new', [])
        if atts:
            counts = {k: atts.count(k) for k in set(atts)}
            buffers['metric.influence_attribution'] = {k: counts[k] / float(len(atts)) for k in counts}

